import { readFileSync } from "fs";

const n = Number(readFileSync(0, "utf8").trim());

const out: string[] = [];
const used = new Array(n + 1).fill(false);
const current: number[] = [];

// 小さい数から順に試すと、辞書順に列挙される
function build(): void {
  if (current.length === n) {
    out.push(current.join(" "));
    return;
  }
  for (let v = 1; v <= n; v++) {
    if (used[v]) continue;
    used[v] = true;
    current.push(v);
    build();
    current.pop();
    used[v] = false;
  }
}
build();
console.log(out.join("\n"));
